sys_script_include.script:
var CreateAdditionalValueBuilderTask = Class.create();
CreateAdditionalValueBuilderTask.prototype = {
    initialize: function() {
        gs.info('Initializing CreateAdditionalValueBuilderTask', 'CreateAdditionalValueBuilderTask');
    },

    createOrUpdateTasks: function(categoryFilter) {
        gs.info('Starting createOrUpdateTasks method with category filter: ' + categoryFilter, 'CreateAdditionalValueBuilderTask');
        var createdTasks = [];
        var updatedTasks = [];
        var processedProperties = [];

        gs.info('Fetching property: sam.implementation.additional.kpis', 'CreateAdditionalValueBuilderTask');
        var propertyName = 'sam.implementation.additional.kpis'; // System property
        var kpiData = gs.getProperty(propertyName);

        if (!kpiData) {
            gs.error('Property "' + propertyName + '" is empty or not set.', 'CreateAdditionalValueBuilderTask');
            return {
                createdTasks,
                updatedTasks,
                processedProperties
            };
        }

        processedProperties.push(propertyName); // Record processed property
        gs.info('Processing Property: ' + propertyName, 'CreateAdditionalValueBuilderTask');

        try {
            gs.info('Parsing KPI data from property', 'CreateAdditionalValueBuilderTask');
            var kpiCategories = JSON.parse(kpiData);

            // Filter categories based on the categoryFilter parameter if provided
            if (categoryFilter) {
                gs.info('Filtering categories by: ' + categoryFilter, 'CreateAdditionalValueBuilderTask');
                var filteredCategories = [];

                for (var i = 0; i < kpiCategories.length; i++) {
                    if (kpiCategories[i].category &&
                        kpiCategories[i].category.toLowerCase() === categoryFilter.toLowerCase()) {
                        filteredCategories.push(kpiCategories[i]);
                        gs.info('Category match found: ' + kpiCategories[i].category, 'CreateAdditionalValueBuilderTask');
                    }
                }

                if (filteredCategories.length === 0) {
                    gs.warning('No categories matched the filter: ' + categoryFilter, 'CreateAdditionalValueBuilderTask');
                }

                kpiCategories = filteredCategories;
            }

            gs.info('Found ' + kpiCategories.length + ' categories to process', 'CreateAdditionalValueBuilderTask');
            var pluginData = this.transform();

            for (var i = 0; i < kpiCategories.length; i++) {
                var category = kpiCategories[i];
                gs.info('Processing category [' + (i + 1) + '/' + kpiCategories.length + ']: ' + category.category, 'CreateAdditionalValueBuilderTask');

                if (!category.category || !category.actions) {
                    gs.error('Invalid category format: ' + JSON.stringify(category), 'CreateAdditionalValueBuilderTask');
                    continue;
                }

                gs.info('Category has ' + category.actions.length + ' actions to process', 'CreateAdditionalValueBuilderTask');
                for (var j = 0; j < category.actions.length; j++) {
                    var action = category.actions[j];
                    gs.info('Processing action [' + (j + 1) + '/' + category.actions.length + ']: ' + action.type, 'CreateAdditionalValueBuilderTask');

                    if (!action.type || !action.description || !action.short_description || !action.instruction) {
                        gs.error('Missing required fields for action: ' + JSON.stringify(action), 'CreateAdditionalValueBuilderTask');
                        continue;
                    }

                    var finalInstruction = action.instruction;

                    // If category type is "Plugin Management", handle plugin-specific actions
                    if (category.category.toLowerCase() === 'plugin management') {
                        gs.info('Plugin Management category detected, processing plugin action: ' + action.type, 'CreateAdditionalValueBuilderTask');

                        // Check if this is specifically an activation task
                        if (action.description.toLowerCase().indexOf('activate') !== -1 ||
                            action.type.toLowerCase().indexOf('activate') !== -1) {
                            gs.info('Plugin activation task detected', 'CreateAdditionalValueBuilderTask');
                            var activationList = pluginData.pluginsToActivate.map(function(p, index) {
                                return (index + 1) + '. ' + p.id + ' (' + p.description + ')';
                            }).join('\n');
                            finalInstruction += '\n\nPlugins to Activate:\n' + (activationList || 'None');
                        } else {
                            gs.info('General plugin management task detected', 'CreateAdditionalValueBuilderTask');
                            var activationList = pluginData.pluginsToActivate.map(function(p, index) {
                                return (index + 1) + '. ' + p.id + ' (' + p.description + ')';
                            }).join('\n');
                            var upgradeList = pluginData.pluginsToUpgrade.map(function(p, index) {
                                return (index + 1) + '. ' + p.id + ' (' + p.description + ')';
                            }).join('\n');
                            finalInstruction += '\n\nPlugins to Activate:\n' + (activationList || 'None') + '\n\nPlugins to Upgrade:\n' + (upgradeList || 'None');
                        }

                        gs.info('Added plugin details to instruction, length: ' + finalInstruction.length, 'CreateAdditionalValueBuilderTask');
                    }

                    // Check if a task with the same description exists
                    gs.info('Checking for existing task with description: ' + action.description, 'CreateAdditionalValueBuilderTask');
                    var existingTask = new GlideRecord('samp_sp_vb_task');
                    existingTask.addQuery('description', action.description);
                    existingTask.addEncodedQuery('stateNOT IN2,-5,3,7'); // Active tasks
                    existingTask.query();

                    if (existingTask.next()) {
                        gs.info('Found existing task, updating: ' + existingTask.sys_id, 'CreateAdditionalValueBuilderTask');
                        // Update existing task
                        existingTask.setValue('short_description', action.short_description);
                        existingTask.setValue('instructions', finalInstruction);
                        existingTask.update();
                        gs.info('Updated task for action: ' + action.type, 'CreateAdditionalValueBuilderTask');
                        updatedTasks.push(action.type);
                    } else {
                        gs.info('No existing task found, creating new task', 'CreateAdditionalValueBuilderTask');
                        // Create new task
                        var taskGr = new GlideRecord('samp_sp_vb_task');
                        taskGr.initialize();
                        taskGr.setValue('short_description', action.short_description);
                        taskGr.setValue('description', action.description);
                        taskGr.setValue('instructions', finalInstruction);

                        gs.info('Inserting new task record', 'CreateAdditionalValueBuilderTask');
                        var taskId = taskGr.insert();
                        if (taskId) {
                            gs.info('Created task for action: ' + action.type + ' (Task ID: ' + taskId + ')', 'CreateAdditionalValueBuilderTask');
                            createdTasks.push(action.type);
                            gs.info('Queueing event: sam.implementation.value.builder.task', 'CreateAdditionalValueBuilderTask');
                            gs.eventQueue('sam.implementation.value.builder.task', taskGr, taskGr.sys_id);
                        } else {
                            gs.error('Failed to create task for action: ' + action.type, 'CreateAdditionalValueBuilderTask');
                        }
                    }
                }
            }
        } catch (e) {
            gs.error('Error processing property "' + propertyName + '": ' + e.message, 'CreateAdditionalValueBuilderTask');
            gs.info('Stack trace: ' + e.stack, 'CreateAdditionalValueBuilderTask');
        }

        gs.info('Completed createOrUpdateTasks method. Created: ' + createdTasks.length +
            ', Updated: ' + updatedTasks.length + ', Properties processed: ' +
            processedProperties.length, 'CreateAdditionalValueBuilderTask');

        return {
            createdTasks: createdTasks,
            updatedTasks: updatedTasks,
            processedProperties: processedProperties
        };
    },

    transform: function() {
        gs.info('Starting transform method to process plugins', 'CreateAdditionalValueBuilderTask');
        var pluginString = gs.getProperty('sam.plugin');
        if (!pluginString) {
            gs.error("Property 'sam.plugin' is empty or not set.", 'CreateAdditionalValueBuilderTask');
            return {
                allPlugins: [],
                pluginsToActivate: [],
                pluginsToUpgrade: []
            };
        }

        try {
            gs.info('Parsing plugin data from sam.plugin property', 'CreateAdditionalValueBuilderTask');
            var pluginArray = JSON.parse(pluginString);
            gs.info('Found ' + pluginArray.length + ' plugins to process', 'CreateAdditionalValueBuilderTask');

            var allPlugins = [];
            var pluginsToActivate = [];
            var pluginsToUpgrade = [];

            for (var i = 0; i < pluginArray.length; i++) {
                var plugin = pluginArray[i];
                gs.info('Processing plugin [' + (i + 1) + '/' + pluginArray.length + ']: ' + plugin.id, 'CreateAdditionalValueBuilderTask');

                var pluginInfo = {
                    id: plugin.id,
                    description: plugin.description,
                    active: GlidePluginManager.isActive(plugin.id)
                };

                gs.info('Plugin ' + plugin.id + ' active status: ' + pluginInfo.active, 'CreateAdditionalValueBuilderTask');

                if (plugin.id.startsWith('sn_')) {
                    gs.info('Processing ServiceNow plugin (sn_): ' + plugin.id, 'CreateAdditionalValueBuilderTask');
                    var sysStoreApp = new GlideRecord('sys_store_app');
                    sysStoreApp.addQuery('scope', plugin.id);
                    sysStoreApp.query();

                    if (sysStoreApp.next()) {
                        pluginInfo.update_available = sysStoreApp.getValue('update_available') == "1";
                        pluginInfo.current_version = sysStoreApp.getValue("version");
                        gs.info('Found plugin in sys_store_app. Version: ' + pluginInfo.current_version +
                            ', Update available: ' + pluginInfo.update_available, 'CreateAdditionalValueBuilderTask');

                        if (pluginInfo.update_available) {
                            gs.info('Checking available version for plugin: ' + plugin.id, 'CreateAdditionalValueBuilderTask');
                            var sysAppVersion = new GlideRecord('sys_app_version');
                            sysAppVersion.addQuery('scope', plugin.id);
                            sysAppVersion.query();

                            if (sysAppVersion.next()) {
                                pluginInfo.available_version = sysAppVersion.getValue('version');
                                gs.info('Found available version: ' + pluginInfo.available_version, 'CreateAdditionalValueBuilderTask');
                            } else {
                                gs.info('No version info found in sys_app_version', 'CreateAdditionalValueBuilderTask');
                            }
                        }
                    } else {
                        gs.info('Plugin not found in sys_store_app: ' + plugin.id, 'CreateAdditionalValueBuilderTask');
                    }
                }

                if (plugin.id.startsWith('com.')) {
                    gs.info('Processing community plugin (com.): ' + plugin.id, 'CreateAdditionalValueBuilderTask');
                    var vPlugin = new GlideRecord('v_plugin');
                    vPlugin.addQuery('id', plugin.id);
                    vPlugin.query();

                    if (vPlugin.next()) {
                        pluginInfo.current_version = vPlugin.getValue('version');
                        pluginInfo.available_version = vPlugin.getValue('available_version');
                        pluginInfo.update_available = pluginInfo.available_version &&
                            pluginInfo.available_version !== pluginInfo.current_version;

                        gs.info('Found plugin in v_plugin. Current version: ' + pluginInfo.current_version +
                            ', Available version: ' + pluginInfo.available_version +
                            ', Update available: ' + pluginInfo.update_available, 'CreateAdditionalValueBuilderTask');
                    } else {
                        gs.info('Plugin not found in v_plugin: ' + plugin.id, 'CreateAdditionalValueBuilderTask');
                    }
                }

                allPlugins.push(pluginInfo);
                if (!pluginInfo.active) {
                    gs.info('Adding plugin to activation list: ' + plugin.id, 'CreateAdditionalValueBuilderTask');
                    pluginsToActivate.push(pluginInfo);
                }
                if (pluginInfo.active && pluginInfo.update_available) {
                    gs.info('Adding plugin to upgrade list: ' + plugin.id, 'CreateAdditionalValueBuilderTask');
                    pluginsToUpgrade.push(pluginInfo);
                }
            }

            gs.info('Transform completed. Total plugins: ' + allPlugins.length +
                ', Plugins to activate: ' + pluginsToActivate.length +
                ', Plugins to upgrade: ' + pluginsToUpgrade.length, 'CreateAdditionalValueBuilderTask');

            return {
                allPlugins,
                pluginsToActivate,
                pluginsToUpgrade
            };
        } catch (e) {
            gs.error("Error processing plugins: " + e.message, 'CreateAdditionalValueBuilderTask');
            return {
                allPlugins: [],
                pluginsToActivate: [],
                pluginsToUpgrade: [],
                error: e.message
            };
        }
    },

    type: 'CreateAdditionalValueBuilderTask'
};
